select customer_id, code, amount, dense_rank() over (partition by customer_id order by amount desc) amount_rank, lag(amount) over (partition by customer_id order by created_at) previous_amount, sum(amount) over (partition by customer_id rows between unbounded preceding and current row) running_amount from orders where created_at >= date '2026-04-01' order by customer_id, amount_rank;
